"""Standalone HTML for the read-only Opening Move Leaders shadow view."""

HTML = r'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>APlus Opening Move Leaders</title>
<style>
:root{--bg:#0b1020;--panel:#121a2d;--muted:#8ea0bd;--text:#e7eefc;--green:#17c964;--red:#f31260;--line:#27334d}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px Segoe UI,Arial,sans-serif}.header{padding:18px 24px;border-bottom:1px solid var(--line);display:flex;justify-content:space-between;gap:12px;align-items:center}.title{font-size:24px;font-weight:750}.sub{color:var(--muted);font-size:12px;margin-top:5px}.links a{color:#7dd3fc;text-decoration:none;margin-left:14px}.notice{margin:16px 24px;padding:12px 14px;border:1px solid #3a4966;border-radius:10px;background:#111a2c;color:#bdcbe2}.meta{padding:0 24px 14px;color:var(--muted)}.grid{display:grid;grid-template-columns:1fr 1fr;gap:14px;padding:0 24px 24px}.box{background:var(--panel);border:1px solid var(--line);border-radius:12px;overflow:hidden}.box h2{font-size:17px;margin:0;padding:13px 15px;border-bottom:1px solid var(--line)}.up{color:#8ff0b4}.down{color:#ff9cac}table{width:100%;border-collapse:collapse}th,td{text-align:left;padding:9px 10px;border-bottom:1px solid var(--line);font-size:12px;white-space:nowrap}th{color:var(--muted)}td.num{text-align:right;font-variant-numeric:tabular-nums}.empty{padding:20px;color:var(--muted)}@media(max-width:850px){.grid{grid-template-columns:1fr}.header{align-items:flex-start;flex-direction:column}.links a{margin:0 12px 0 0}}
</style></head><body>
<div class="header"><div><div class="title">Opening Move Leaders <span style="font-size:12px;color:#8ea0bd">SHADOW / INFORMATION ONLY</span></div><div class="sub">Separate gainers and decliners, ordered by reported change from the 09:15 open.</div></div><div class="links"><a href="/fno-market-watch">F&amp;O Market Watch</a><a href="/">Trading Terminal</a></div></div>
<div class="notice"><b>Read-only observer.</b> This page uses the scanner's existing F&amp;O report. It does not create entries or change strategy and is not a trade recommendation. The report does not contain first-minute candle volume, relative volume, or VWAP confirmation; no institutional-flow claim is made.</div>
<div class="meta" id="meta">Loading existing scanner report...</div>
<div class="grid"><section class="box"><h2 class="up">&#9650; Leaders from open</h2><div id="up"></div></section><section class="box"><h2 class="down">&#9660; Laggards from open</h2><div id="down"></div></section></div>
<script>
function n(v){return v==null?"—":Number(v).toFixed(2)}
function table(rows,cls){if(!rows.length)return '<div class="empty">No ranked rows in the current report.</div>';return '<div style="overflow:auto"><table><thead><tr><th>#</th><th>Symbol</th><th>Sector</th><th>09:15 Open</th><th>LTP</th><th>From Open</th><th>Gap</th><th>Range Position</th></tr></thead><tbody>'+rows.map(x=>'<tr><td>'+x.rank+'</td><td><b>'+x.symbol+'</b></td><td>'+x.sector+'</td><td class="num">'+n(x.open_0915)+'</td><td class="num">'+n(x.ltp)+'</td><td class="num '+cls+'">'+(x.from_open_pct>0?'+':'')+n(x.from_open_pct)+'%</td><td class="num">'+(x.gap_pct==null?'—':(x.gap_pct>0?'+':'')+n(x.gap_pct)+'%')+'</td><td class="num">'+(x.range_position_pct==null?'—':n(x.range_position_pct)+'%')+'</td></tr>').join('')+'</tbody></table></div>'}
async function load(){try{const r=await fetch('/api/opening-leaders',{cache:'no-store'}),d=await r.json();document.getElementById('up').innerHTML=table(d.gainers||[],'up');document.getElementById('down').innerHTML=table(d.decliners||[],'down');const age=d.age_seconds==null?'age unavailable':Math.max(0,Math.floor(d.age_seconds))+' sec old';document.getElementById('meta').textContent=(d.stale?'STALE - ':'')+'Scanner report: '+(d.generated_at||'timestamp unavailable')+' | '+age+' | '+d.count+' rows'+(d.stale_reason?' | '+d.stale_reason:'');}catch(e){document.getElementById('meta').textContent='Could not read the existing scanner report.'}}load();setInterval(load,5000)
</script></body></html>'''

